mapper.select:
select 
from club_event_series
where club_id = #{clubId} and created_by_member_id = #{actorMemberId}
  and request_id = #{requestId}
limit 1

select 
from club_event_series
where club_id = #{clubId} and created_by_member_id = #{actorMemberId}
  and request_id = #{requestId}
limit 1 for update

select o.id, o.series_id, o.activity_id, o.occurrence_at,
       o.default_lead_member_id, o.status, o.version, o.create_time
from club_event_occurrence o
inner join club_event_series s on s.id = o.series_id and s.club_id = #{clubId}
  and s.status in ('ACTIVE', 'CLOSED')
inner join cms_activity a on a.id = o.activity_id and a.club_id = #{clubId}
  and a.del_flag = 0 and a.start_date >= #{now} and o.occurrence_at >= #{now}
where o.series_id = #{seriesId} and o.status = 'ACTIVE'
order by o.occurrence_at asc, o.id asc

select case when exists (
  select 1 from cms_activity a
  where a.id = #{activityId} and ifnull(a.is_settlement, 0) <> 0
) or exists (
  select 1 from cms_registration r
  where r.owner_type = 2 and r.owner_id = #{activityId}
) or exists (
  select 1 from club_event_waitlist w
  where w.activity_id = #{activityId} and w.state in ('WAITING','OFFERED','CLAIMED')
) then 1 else 0 end

mapper.update:
update cms_activity a
set a.status = 0, a.publish_status = 0, a.cancel_time = #{now},
    a.cancel_reason = '系列未来场次重排', a.update_by = #{username}, a.update_time = #{now}
where a.id = #{activityId} and a.del_flag = 0 and a.start_date > #{now}
  and ifnull(a.is_settlement, 0) = 0
  and not exists (
    select 1 from cms_registration r
    where r.owner_type = 2 and r.owner_id = a.id
  )

update club_event_occurrence
set status = 'CANCELLED', version = version + 1
where id = #{id} and status = 'ACTIVE' and version = #{expectedVersion}

update club_event_series
set status = 'CLOSED', version = version + 1,
    update_by = #{username}, update_time = #{now}
where id = #{seriesId} and club_id = #{clubId}
  and status = 'ACTIVE' and version = #{expectedVersion}

update club_event_series
set recurrence_type = #{recurrenceType}, version = version + 1,
    update_by = #{username}, update_time = #{now}
where id = #{seriesId} and status = 'ACTIVE' and version = #{expectedVersion}

mapper.select:
select case when exists (
  select 1 from club c
  where c.id = #{clubId} and c.status = 1 and c.del_flag = 0
    and (c.member_id = #{memberId} or exists (
      select 1 from club_member cm
      where cm.club_id = c.id and cm.member_id = #{memberId}
        and cm.status = 1 and cm.del_flag = 0
    ))
) then 1 else 0 end

select id from cms_activity
where id = #{activityId} and club_id = #{clubId}
  and status = 1 and publish_status = 1 and del_flag = 0
  and end_date > #{now}
for update

select member_id from club
where id = #{clubId}
for update

select count(*) from cms_registration
where owner_type = 2 and owner_id = #{activityId} and ticket_id = #{ticketId}
  and member_id = #{memberId}
  and registration_status in (1, 2) and payment_status in (0, 1, 2)

mapper.update:
update club_event_waitlist
set state = 'CANCELLED', version = version + 1
where id = #{id} and state = #{expectedState} and version = #{expectedVersion}
  and member_id = #{memberId} and activity_id = #{activityId} and ticket_id = #{ticketId}

update club_event_waitlist
set state = 'CLAIMED', version = version + 1
where id = #{id} and state = 'OFFERED' and version = #{expectedVersion}
  and member_id = #{memberId} and activity_id = #{activityId} and ticket_id = #{ticketId}
  and offer_expires_at > #{now}

choose.otherwise:
select w.id as scanId,
w.idw.registration_id as targetId
from club_event_waitlist w
inner join cms_registration r on r.id = w.registration_id
where w.id > #{afterId} and w.id <= #{maxId}

    and w.state = 'OFFERED' and w.offer_expires_at <= #{now}
    and w.state = 'CLAIMED' and r.payment_status = 2 and r.registration_status = 2
    and w.state = 'CLAIMED' and (r.registration_status in (3, 4) or r.payment_status in (3, 4))
    and 1 = 0

order by w.id asc limit #{limit}

mapper.select:
select id from club_event_waitlist
where state = 'OFFERED' and offer_expires_at <= #{now}
order by offer_expires_at asc, id asc limit #{limit}

mapper.update:
update club_event_waitlist
set state = 'EXPIRED', version = version + 1
where id = #{id} and state = 'OFFERED' and version = #{expectedVersion}
  and offer_expires_at <= #{now}

mapper.sql:
and not exists (
  select 1 from club_governance_ban ban
  where ban.club_id = #{clubId} and ban.target_member_id = #{recipientMemberId}
    and ban.status = 'ACTIVE'
    and (ban.source_type <> 'CLUB' or ban.expires_at is null or ban.expires_at > now())
)

choose.when:
select exists (
  select 1 from club c
  where c.id = #{clubId} and c.status = 1 and c.del_flag = 0
    and c.member_id = #{recipientMemberId}

  union all
  select 1 from club_member cm
  inner join club c on c.id = cm.club_id and c.status = 1 and c.del_flag = 0
  where cm.club_id = #{clubId} and cm.member_id = #{recipientMemberId}
    and cm.status = 1 and cm.del_flag = 0

)

select exists ( select 1 from club c where c.id = #{clubId} and c.status = 1 and c.del_flag = 0 and c.member_id = #{recipientMemberId}
union all select 1 from club_role_assignment cra inner join club_member cm on cm.club_id = cra.club_id and cm.member_id = cra.target_member_id and cm.status = 1 and cm.del_flag = 0 inner join club c on c.id = cra.club_id and c.status = 1 and c.del_flag = 0 where cra.club_id = #{clubId} and cra.target_member_id = #{recipientMemberId} and cra.scope_type = 'CLUB' and cra.scope_id = #{clubId} and cra.role_code in ('CLUB_CO_OWNER','CLUB_OPERATOR') and cra.status = 'ACTIVE' and (cra.expires_at is null or cra.expires_at > now())
)

select exists ( select 1 from club_event_notification_campaign nc inner join club_event_notification_delivery nd on nd.campaign_id = nc.id and nd.recipient_member_id = #{recipientMemberId} inner join cms_activity a on a.id = nc.activity_id and a.club_id = nc.club_id and a.del_flag = 0 and a.cancel_time is not null and a.publish_status = 0 inner join club_event_occurrence o on o.activity_id = a.id and o.status = 'CANCELLED' inner join club_event_series s on s.id = o.series_id and s.club_id = a.club_id inner join club c on c.id = a.club_id and c.status = 1 and c.del_flag = 0 where nc.id = #{campaignId} and nc.club_id = #{clubId} and nc.activity_id = #{activityId} and nc.audience_type = 'REGISTERED' and nc.request_id like 'cancel-r-%'
union all select 1 from cms_registration r inner join cms_activity a on a.id = r.owner_id and a.id = #{activityId} and a.club_id = #{clubId} and a.del_flag = 0 inner join club c on c.id = a.club_id and c.status = 1 and c.del_flag = 0 inner join club_event_notification_campaign nc on nc.id = #{campaignId} and nc.club_id = #{clubId} and nc.activity_id = #{activityId} and nc.audience_type = 'REGISTERED' and nc.request_id not like 'cancel-r-%' and nc.request_id not like 'cancel-w-%' where r.owner_type = 2 and r.owner_id = #{activityId} and r.member_id = #{recipientMemberId} and r.payment_status = 2 and r.registration_status = 2
)

select exists ( select 1 from club_event_notification_campaign nc inner join club_event_notification_delivery nd on nd.campaign_id = nc.id and nd.recipient_member_id = #{recipientMemberId} inner join cms_activity a on a.id = nc.activity_id and a.club_id = nc.club_id and a.del_flag = 0 and a.cancel_time is not null and a.publish_status = 0 inner join club_event_occurrence o on o.activity_id = a.id and o.status = 'CANCELLED' inner join club_event_series s on s.id = o.series_id and s.club_id = a.club_id inner join club c on c.id = a.club_id and c.status = 1 and c.del_flag = 0 where nc.id = #{campaignId} and nc.club_id = #{clubId} and nc.activity_id = #{activityId} and nc.audience_type = 'WAITLIST' and nc.request_id like 'cancel-w-%'
union all select 1 from club_event_waitlist w inner join cms_activity a on a.id = w.activity_id and a.club_id = w.club_id and a.del_flag = 0 inner join club c on c.id = w.club_id and c.status = 1 and c.del_flag = 0 inner join club_event_notification_campaign nc on nc.id = #{campaignId} and nc.club_id = #{clubId} and nc.activity_id = #{activityId} and nc.audience_type = 'WAITLIST' and nc.request_id not like 'cancel-r-%' and nc.request_id not like 'cancel-w-%' where w.club_id = #{clubId} and w.activity_id = #{activityId} and w.member_id = #{recipientMemberId} and w.state in ('WAITING','OFFERED','CLAIMED') and (c.member_id = #{recipientMemberId} or exists ( select 1 from club_member cm where cm.club_id = w.club_id and cm.member_id = #{recipientMemberId} and cm.status = 1 and cm.del_flag = 0 ))
)

select exists ( select 1 from ( select c.member_id from club c where c.id = #{clubId} and c.status = 1 and c.del_flag = 0 and c.member_id = #{recipientMemberId}
union select cm.member_id from club_member cm inner join club c on c.id = cm.club_id and c.status = 1 and c.del_flag = 0 where cm.club_id = #{clubId} and cm.status = 1 and cm.del_flag = 0 and cm.member_id = #{recipientMemberId}
) members where not exists ( select 1 from cms_registration r inner join cms_activity a on a.id = r.owner_id and a.club_id = #{clubId} and a.del_flag = 0 where r.owner_type = 2 and r.member_id = members.member_id and r.payment_status = 2 and r.registration_status = 2 and r.payment_time >= date_sub(now(), interval 90 day) ) )

mapper.select:
select distinct d.campaign_id
from club_event_notification_outbox o
inner join club_event_notification_delivery d on d.id = o.delivery_id
  and d.status in ('PENDING','FAILED') and d.attempt_count < 5
where o.status = 'PENDING' and o.next_attempt_at <= #{now}
order by d.campaign_id asc limit #{limit}

mapper.update:
update club_event_notification_delivery
set status = 'SENT', attempt_count = attempt_count + 1, message_id = #{messageId},
    sent_at = #{sentAt}, last_error = null, version = version + 1, update_time = #{sentAt}
where id = #{id} and status in ('PENDING','FAILED') and version = #{expectedVersion}
